export type ThemeName = "light" | "dark";

export interface ThemeTokens {
  /** Main actions, links, focus, active menu items */
  primary: string;
  /** Text/icons on top of primary */
  primaryForeground: string;
  /** Success, active */
  success: string;
  /** Needs attention */
  warning: string;
  /** Delete, failed, error */
  danger: string;
  /** Information */
  info: string;
  /** Card, dialog, and input background */
  background: string;
  /** Page background */
  surface: string;
  /** Hover, table header, and chip background */
  muted: string;
  /** Lines and dividers */
  border: string;
  /** Primary text */
  foreground: string;
  /** Secondary text, placeholder */
  mutedForeground: string;
  /** Sidebar background */
  sidebar: string;
  /** Menu text and icons in the sidebar */
  sidebarForeground: string;
  radiusSm: string;
  radiusMd: string;
  radiusLg: string;
  radiusXl: string;
  pagePadding: string;
  cardPadding: string;
  sectionGap: string;
  stackGap: string;
  fieldGap: string;
  /** Primary UI font */
  fontFamily: string;
}

